        await client.remove(ids)
        CookPlanCancelDiagnostic.mark("remove-after")
        CookPlanCancelDiagnostic.mark("pending-ids-before")
        let remaining = await client.pendingIDs()
        CookPlanCancelDiagnostic.mark("pending-ids-after")
